<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/Core.php';use Wams\Core;$c=new Core();$error='';$done=false;if((int)$c->db->query('SELECT COUNT(*) FROM users')->fetchColumn()>0){http_response_code(404);exit;}
if($_SERVER['REQUEST_METHOD']==='POST')try{$name=trim((string)$_POST['username']);$pass=(string)$_POST['password'];$repo=trim((string)$_POST['repository']);if($name===''||strlen($pass)<12)throw new RuntimeException('Benutzername und mindestens 12 Zeichen Passwort erforderlich.');$c->setSetting('app_repository',$repo);$c->refreshRepository();$c->db->prepare('INSERT INTO users VALUES(?,?,?,?,?,?)')->execute([$c->id(),$name,password_hash($pass,PASSWORD_ARGON2ID),1,1,gmdate('c')]);$done=true;}catch(Throwable$e){$error=$e->getMessage();}
function h(mixed$v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/style.css"><title>WAMS Setup</title></head><body class="login-page"><main class="login"><h1>WAMS Setup</h1><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><?php if($done):?><p>Einrichtung abgeschlossen.</p><a class="button" href="/login">Anmelden</a><?php else:?><form method="post"><label>Benutzername</label><input name="username" required autofocus><label>Passwort</label><input type="password" name="password" minlength="12" required><label>App-Repository</label><input type="url" name="repository" value="https://github.com/florianthepro/webapp-foundry" required><button>Einrichten</button></form><?php endif?></main></body></html>
